export const securityPlusDepthById = Object.fromEntries(profiles.map((profile, index) => [profile.id, securityPlusDepth[index]]));

profiles.forEach((profile) => {
  const depth = securityPlusDepthById[profile.id];
  profile.depth = depth;
  profile.theory.push(...depth.theory);
  profile.sources = [...new Set([...profile.sources, 'sp-messer', ...depth.sources.map(([id]) => id)])];
});

