export const securityPlusLessonResources = Object.fromEntries(profiles.map((profile) => [profile.id, profile.sources.map((sourceId, index) => ({
  sourceId,
  focus: profile.depth.sources.find(([id]) => id === sourceId)?.[1]
    || (sourceId === 'sp-messer' ? `Откройте оригинальный плейлист Professor Messer и найдите видео по теме «${profile.title}». На этой платформе опубликована самостоятельная учебная разработка, а не транскрипт видео.`
      : index === 0 ? `Сверьте терминологию и границы домена для темы «${profile.title}» с официальными целями SY0-701; перед экзаменом проверьте актуальный код.`
        : `Используйте открытый материал для углубления темы «${profile.title}» и проверки защитной лаборатории.`),
  ...(index === 0 ? { takeaway: profile.defense } : {}),
}))]));
